import{createRequire}from'node:module';import{join}from'node:path';import{readFile,writeFile,mkdir}from'node:fs/promises';import assert from'node:assert/strict';const r=createRequire(join(process.env.SDS_BROWSER_MODULES,'package.json')),origin=process.env.SDS_PREVIEW_ORIGIN||'http://127.0.0.1:31861',out=process.env.SDS_DOCUMENT_OUT||'/tmp/sds-document-controls';await mkdir(out,{recursive:true});const axe=await readFile(r.resolve('axe-core/axe.min.js'),'utf8'),b=await r('puppeteer-core').launch({executablePath:'/usr/local/bin/google-chrome',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});const report={views:[],actions:[]};async function shot(p,name,width,theme){await p.addScriptTag({content:axe});const a=await p.evaluate(async()=>{const a=await axe.run(document,{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21a','wcag21aa']}});return {axe:a.violations.map(v=>({id:v.id,nodes:v.nodes.map(n=>({target:n.target,summary:n.failureSummary}))})),scrollWidth:document.documentElement.scrollWidth}});const screenshot=name+'-'+width+'-'+theme+'.jpg';await p.screenshot({path:out+'/'+screenshot,type:'jpeg',quality:75});report.views.push({name,width,theme,screenshot,...a});await writeFile(out+'/report.json',JSON.stringify(report,null,2));}
try{for(const width of[390,768,1440])for(const theme of['drafting','dark']){const c=await b.createBrowserContext(),p=await c.newPage();await p.setViewport({width,height:900});await p.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);await p.evaluateOnNewDocument(t=>{localStorage.setItem('sourcey-theme',t==='dark'?'dark':'light');localStorage.setItem('sdd-theme',t)},theme);await p.goto(origin+'/docs/rust-itertools/pkg-itertools-itertools-structs.html',{waitUntil:'networkidle2'});const hasTheme=await p.$eval('#theme-toggle',e=>!!e.getClientRects().length);if(hasTheme){await p.focus('#theme-toggle');await p.keyboard.press('Enter');await p.waitForFunction(t=>document.documentElement.classList.contains('dark')===t,{},theme!=='dark');await p.waitForFunction(()=>!document.documentElement.matches(':active-view-transition'));await p.keyboard.press('Enter');await p.waitForFunction(t=>document.documentElement.classList.contains('dark')===t,{},theme==='dark');await p.waitForFunction(()=>!document.documentElement.matches(':active-view-transition'));assert.equal(await p.$eval('html',e=>e.classList.contains('dark')),theme==='dark');}const hasMenu=await p.$eval('button[aria-label="Open menu"]',e=>!!e.getClientRects().length);if(hasMenu){await p.focus('button[aria-label="Open menu"]');await p.keyboard.press('Enter');assert.equal(await p.$eval('#mobile-nav',e=>e.open),true);assert.equal(await p.$eval('#mobile-nav',e=>getComputedStyle(e).animationName),'none');await shot(p,'documentation-mobile-menu',width,theme);await p.keyboard.press('Escape');await p.waitForFunction(()=>!document.getElementById('mobile-nav').getClientRects().length);assert.equal(await p.$eval('#mobile-nav',e=>e.open),false);}await p.keyboard.press('/');await p.waitForSelector('#search-dialog.open');await p.type('#search-input','Interleave');await p.waitForSelector('.search-result');await shot(p,'documentation-search-results',width,theme);await p.keyboard.press('Escape');await p.waitForFunction(()=>document.activeElement.tagName==='BUTTON'&&!!document.activeElement.getClientRects().length);const focus=await p.evaluate(()=>({id:document.activeElement.id,visible:!!document.activeElement.getClientRects().length,expanded:document.activeElement.getAttribute('aria-expanded')}));assert.equal(focus.visible,true);assert.notEqual(focus.id,'search-input');await p.keyboard.press('/');await p.waitForSelector('#search-dialog.open');await p.type('#search-input','Interleave');await p.waitForSelector('.search-result');await p.keyboard.press('ArrowDown');await p.keyboard.press('ArrowUp');await p.keyboard.press('Enter');await p.waitForFunction(()=>location.hash==='#reexport.Interleave');assert.equal(await p.$eval('#search-dialog',e=>e.classList.contains('open')),false);assert.ok(await p.$('#reexport\\.Interleave'));await shot(p,'documentation-selected-symbol',width,theme);report.actions.push({width,theme,searchKeyboard:true,escapeFocus:focus,selectedPublishedSymbol:true,mobileDisclosure:hasMenu,themeButton:hasTheme});await c.close();console.log('DOCUMENT',width,theme);}}finally{await b.close();await writeFile(out+'/report.json',JSON.stringify(report,null,2));}
